script:
test("round a non-multiple up and ship cases times case size", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 25, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("an order that rounds to fewer than 2 cases is raised to 2", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 5, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("an exact multiple is not rounded further and a result of exactly 2 is not raised", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 24, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("a result of exactly 1 case, the threshold minus one, is raised to 2", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 12, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("one unit below one case still rounds to 1 and is raised to 2", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 11, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("the smallest positive order rounds to 1 case and is raised to 2", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 1, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("one unit above one case rounds to exactly 2 and is not raised further", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 13, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("one unit below two cases rounds up to exactly 2 and ships 2 cases", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 23, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("one unit above two cases, with case size taken from the input, rounds up to 3", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 17, caseSize: 8 }), { cases: 3, shippedUnits: 24 });
});

test("exactly two cases for a non-example case size stays 2", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 16, caseSize: 8 }), { cases: 2, shippedUnits: 16 });
});

test("an exact multiple above the minimum is not rounded further", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 24, caseSize: 8 }), { cases: 3, shippedUnits: 24 });
});

test("one unit below an exact multiple rounds up by one case only", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 23, caseSize: 8 }), { cases: 3, shippedUnits: 24 });
});

test("the exact halfway value 30/12 = 2.5 rounds up to 3", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 30, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("one input step below halfway, 29/12, rounds up to 3", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 29, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("one input step above halfway, 31/12, rounds up to 3", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 31, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("the same quantity in integer and decimal form", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 25, caseSize: 12.0 }), { cases: 3, shippedUnits: 36 });
});
